mapper.update:
UPDATE orders
SET status = #{status},
    payment_status = #{paymentStatus}
WHERE order_id = #{id}
  AND status = #{fromStatus}
  AND payment_status = #{fromPaymentStatus}

UPDATE orders
SET paid_balance = #{paidBalance},
    paid_points = #{paidPoints},
    earned_points = #{earnedPoints}
WHERE order_id = #{id}

mapper.select:
SELECT order_id FROM orders
WHERE status = 'PENDING' AND payment_status = 'UNPAID' AND created_at <= #{before}
ORDER BY order_id
